const { evaluate } = require('./s5_expr.js');

// Test basic functionality still works
console.log("Testing basic expressions...");
console.assert(evaluate("2 + 3") === 5, "2 + 3 should equal 5");
console.assert(evaluate("10 - 4") === 6, "10 - 4 should equal 6");
console.assert(evaluate("3 * 7") === 21, "3 * 7 should equal 21");
console.assert(evaluate("15 / 3") === 5, "15 / 3 should equal 5");
console.log("Basic expressions work!");

// Test variable functionality
console.log("Testing variable expressions...");
const vars = { x: 5, y: 3, z: 2.5 };
console.assert(evaluate("x + y", vars) === 8, "x + y should equal 8");
console.assert(evaluate("x * y", vars) === 15, "x * y should equal 15");
console.assert(evaluate("x + y * z", vars) === 12.5, "x + y * z should equal 12.5");
console.assert(evaluate("(x + y) * z", vars) === 27.5, "(x + y) * z should equal 27.5");
console.log("Variable expressions work!");

// Test error handling for unknown variables
console.log("Testing error handling...");
try {
    evaluate("unknown_var", {});
    console.error("Should have thrown an error for unknown variable");
    process.exit(1);
} catch (e) {
    if (e.message.includes("unknown_var")) {
        console.log("Unknown variable error handling works!");
    } else {
        console.error("Wrong error message:", e.message);
        process.exit(1);
    }
}

try {
    evaluate("x + unknown_var", { x: 5 });
    console.error("Should have thrown an error for unknown variable");
    process.exit(1);
} catch (e) {
    if (e.message.includes("unknown_var")) {
        console.log("Unknown variable error handling works for mixed expressions!");
    } else {
        console.error("Wrong error message:", e.message);
        process.exit(1);
    }
}

console.log("All tests passed!");

